use mbse_model::{stage1::*,types::{self as t,admission as a},extensions::Extensions};
use serde_json::{Value,json};
use std::collections::BTreeMap;
const NATIVE:&[u8]=include_bytes!("../../../docs/parity/p38b/verification/native-01/cold-run/project-set-target-cold-copy.kernspan");
const VIEWS:&[u8]=include_bytes!("../../../docs/parity/p38b/verification/native-01/cold-run/project-set-target-cold-copy.mbse-views.json");
fn editor()->Editor{let snapshot=serde_json::from_slice::<Value>(NATIVE).unwrap()["snapshot"].clone();Editor::new(serde_json::from_value(snapshot).unwrap(),"admission:test:runtime".into()).unwrap()}
fn source()->a::Source{a::Source{member:"supplier".into(),primary_sha256:"a".repeat(64)}}
fn payload()->a::Payload{a::Payload{model_id:"model".into(),model_name:"Source model retains its name as metadata".into(),components:vec![a::Component{source_id:"A".into(),name:"Assembly".into(),block:Some(a::BlockDeclaration{source_id:"blockA".into(),namespace:a::BLOCK_NAMESPACE.into()})},a::Component{source_id:"B".into(),name:"Sensor".into(),block:None}],usages:vec![a::ComponentUsage{source_id:"part".into(),name:"sensor".into(),owner:"A".into(),target:"B".into(),kind:t::UsageKind::Part},a::ComponentUsage{source_id:"ref".into(),name:"assemblyReference".into(),owner:"B".into(),target:"A".into(),kind:t::UsageKind::Reference}]}}
fn plan(e:&Editor)->a::Plan{a::prepare(e,RecordId(1),source(),payload()).unwrap()}
fn apply(e:&mut Editor,p:a::Plan)->Result<(),String>{e.command(&e.freshness(),Command::Typed(t::Action::Admission(Box::new(p)))).map(|_|())}
fn preserved(before:&Snapshot,after:&Snapshot){assert_eq!(after.records,before.records);assert_eq!(after.drafts,before.drafts);assert_eq!(after.creation_drafts,before.creation_drafts);let mut ns=after.extensions.as_ref().unwrap().namespaces.clone();ns.insert(t::NAMESPACE.into(),before.extensions.as_ref().unwrap().namespaces[t::NAMESPACE].clone());assert_eq!(ns,before.extensions.as_ref().unwrap().namespaces);let old=t::load(before).unwrap();let mut new=t::load(after).unwrap();new.definitions.retain(|id,_|old.definitions.contains_key(id));new.usages.retain(|id,_|old.usages.contains_key(id));new.profiles.retain(|id,_|old.profiles.contains_key(id));new.profile_applications.retain(|id,_|old.profile_applications.contains_key(id));assert_eq!(new,old);}
#[test]
fn admission_prepare_is_pure_and_append_keeps_all_prior_native_typed_raw_opaque_meaning_and_exact_correspondence(){
 let mut e=editor();let before=e.snapshot.clone();let p=plan(&e);assert_eq!(e.snapshot,before);assert!(!e.can_undo());let summary=serde_json::to_value(p.summary()).unwrap();assert_eq!(summary["correspondences"].as_array().unwrap().len(),6);assert_eq!(summary["created_components"],2);assert_eq!(summary["created_usages"],2);assert_eq!(summary["declared_blocks"],1);assert_eq!(summary["correspondences"][0]["native"],1);apply(&mut e,p).unwrap();preserved(&before,&e.snapshot);assert_eq!(e.snapshot.model_revision,before.model_revision+1);assert_eq!(e.snapshot.raw_version,before.raw_version);assert_eq!(e.snapshot.next_id,before.next_id+4);let s=t::load(&e.snapshot).unwrap();let a=t::Id(before.next_id);let b=t::Id(before.next_id+1);assert_eq!(s.definitions[&a].kind,t::Kind::Component);assert_eq!(s.usages[&t::Id(before.next_id+2)].target,b);assert_eq!(s.usages[&t::Id(before.next_id+3)].target,a);let apps:Vec<_>=s.profile_applications.values().filter(|p|p.profile.namespace==a::PROVENANCE_NAMESPACE).collect();assert_eq!(apps.len(),5);assert!(apps.iter().all(|p|p.values["model_id"].text=="model"&&p.values["member"].text=="supplier"&&p.values["primary_sha256"].text=="a".repeat(64)));assert!(apps.iter().any(|p|p.stereotype=="BlockDeclaration"&&p.target==a&&p.values["source_namespace"].text==a::BLOCK_NAMESPACE));
}
#[test]
fn admission_single_model_undo_redo_retains_newer_invalid_native_and_type_journals_and_never_rewinds_ids(){
 let mut e=editor();let before=e.snapshot.clone();let p=plan(&e);apply(&mut e,p).unwrap();let accepted=t::load(&e.snapshot).unwrap();let next=e.snapshot.next_id;
 e.command(&e.freshness(),Command::EditText{key:RawKey{record:RecordId(1003),field:"criterion".into(),item:None},text:"9e-".into()}).unwrap();e.command(&e.freshness(),Command::Typed(t::Action::SetUsageForm{form:t::UsageForm{id:None,name:"unfinished import usage +".into(),owner:(next-4).to_string(),target:"not-an-id".into(),kind:t::UsageKind::Reference}})).unwrap();let raw=e.snapshot.drafts.clone();let journals=t::drafts_value(&e.snapshot.extensions);assert!(e.undo_model(&e.freshness()).unwrap());assert_eq!(t::load(&e.snapshot).unwrap(),t::load(&before).unwrap());assert_eq!(e.snapshot.records,before.records);assert_eq!(e.snapshot.drafts,raw);assert_eq!(t::drafts_value(&e.snapshot.extensions),journals);assert_eq!(e.snapshot.next_id,next);assert!(!e.undo_model(&e.freshness()).unwrap());assert!(e.redo_model(&e.freshness()).unwrap());assert_eq!(t::load(&e.snapshot).unwrap(),accepted);assert_eq!(e.snapshot.drafts,raw);assert_eq!(t::drafts_value(&e.snapshot.extensions),journals);assert_eq!(e.snapshot.next_id,next);
}
#[test]
fn admission_foreign_runtime_same_counter_changed_raw_opaque_allocator_and_replayed_plans_refuse_atomically(){
 let original=editor();for variant in["runtime","raw","opaque","allocator"]{let p=plan(&original);let mut e=editor();match variant{"runtime"=>e=Editor::new(e.snapshot,"other:runtime".into()).unwrap(),"raw"=>e.snapshot.drafts.iter_mut().find(|d|d.key.record==RecordId(1003)&&d.key.field=="criterion").unwrap().text="9e-".into(),"opaque"=>{e.snapshot.extensions.as_mut().unwrap().namespaces.insert("example.uninterpreted-admission-test".into(),json!({"different":true}));},_=>e.snapshot.next_id+=1};let before=e.snapshot.clone();assert!(apply(&mut e,p).unwrap_err().contains("STALE_OR_FOREIGN"));assert_eq!(e.snapshot,before);assert!(!e.can_undo());}
 let mut e=editor();let p=plan(&e);apply(&mut e,p.clone()).unwrap();let before=e.snapshot.clone();assert!(apply(&mut e,p).is_err());assert_eq!(e.snapshot,before);
}
#[test]
fn admission_duplicate_missing_owner_target_native_id_alias_and_unsupported_block_namespace_refuse_without_reserving_ids(){
 let e=editor();let before=e.snapshot.clone();for variant in["duplicate","model-id","owner","target","native-alias","namespace","empty-name"]{let mut payload=payload();match variant{"duplicate"=>payload.usages[0].source_id="A".into(),"model-id"=>payload.components[0].block.as_mut().unwrap().source_id="model".into(),"owner"=>payload.usages[0].owner="missing".into(),"target"=>payload.usages[0].target="missing".into(),"native-alias"=>payload.usages[0].target="1009".into(),"namespace"=>payload.components[0].block.as_mut().unwrap().namespace="urn:unsupported:SysML".into(),_=>payload.components[0].name=" ".into()};assert!(a::prepare(&e,RecordId(1),source(),payload).is_err(),"{variant}");assert_eq!(e.snapshot,before);}
}
#[test]
fn admission_containment_cycles_use_existing_native_validator_while_reference_cycles_remain_noncontaining(){
 let mut e=editor();let before=e.snapshot.clone();let mut cycle=payload();cycle.usages[1].kind=t::UsageKind::Part;assert!(a::prepare(&e,RecordId(1),source(),cycle).is_err());assert_eq!(e.snapshot,before);let mut references=payload();references.usages[0].kind=t::UsageKind::Reference;let p=a::prepare(&e,RecordId(1),source(),references).unwrap();apply(&mut e,p).unwrap();preserved(&before,&e.snapshot);
}
#[test]
fn admission_provenance_profile_collision_and_repeated_exact_source_refuse_but_another_member_keeps_fresh_identities(){
 let mut e=editor();apply(&mut e,plan(&editor())).unwrap();let before=e.snapshot.clone();assert!(a::prepare(&e,RecordId(1),source(),payload()).unwrap_err().contains("ALREADY_ATTACHED"));assert_eq!(e.snapshot,before);let mut other=source();other.member="consumer".into();let p=a::prepare(&e,RecordId(1),other,payload()).unwrap();assert!(p.summary().correspondences.iter().filter(|c|c.source_kind=="UmlClass").all(|c|c.native.0>=before.next_id));apply(&mut e,p).unwrap();
 let mut e=editor();let mut store=t::load(&e.snapshot).unwrap();let key=format!("{}|1",a::PROVENANCE_NAMESPACE);store.profiles.insert(key,t::tags::Profile{identity:t::tags::Identity{namespace:a::PROVENANCE_NAMESPACE.into(),version:"1".into()},stereotypes:BTreeMap::from([("Foreign".into(),t::tags::Stereotype{applies_to:[t::tags::TargetKind::ComponentDefinition].into_iter().collect(),tags:BTreeMap::new()})])});e.snapshot.extensions.as_mut().unwrap().namespaces.insert(t::NAMESPACE.into(),serde_json::to_value(store).unwrap());e.snapshot.validate().unwrap();let before=e.snapshot.clone();assert!(a::prepare(&e,RecordId(1),source(),payload()).unwrap_err().contains("PROFILE_COLLISION"));assert_eq!(e.snapshot,before);
}
#[test]
fn admission_exact_identity_and_utf8_text_limits_refuse_oversized_or_aliased_context_without_truncation(){
 let e=editor();let mut p=payload();p.usages.clear();p.components=(0..63).map(|i|a::Component{source_id:format!("c{i}"),name:"é".repeat(128),block:None}).collect();let candidate=a::prepare(&e,RecordId(1),source(),p.clone()).unwrap();assert_eq!(candidate.summary().correspondences.len(),64);p.components.push(a::Component{source_id:"over".into(),name:"extra".into(),block:None});assert!(a::prepare(&e,RecordId(1),source(),p).unwrap_err().contains("IDENTITY_LIMIT"));for variant in["member","hash","id","name"]{let mut p=payload();let mut s=source();match variant{"member"=>s.member="a/b".into(),"hash"=>s.primary_sha256="A".repeat(64),"id"=>p.model_id="has whitespace".into(),_=>p.components[0].name="é".repeat(129)};assert!(a::prepare(&e,RecordId(1),s,p).is_err());}
}
#[test]
fn admission_legacy_opaque_type_collision_wrong_system_and_existing_global_capacity_are_explicit_and_atomic(){
 let mut legacy=Snapshot::new(DocumentId("legacy:admission".into()));for variant in["legacy","opaque","wrong-system","capacity"]{let mut e=if variant=="legacy"||variant=="opaque"{if variant=="opaque"{let mut ext=Extensions::default();ext.namespaces.insert(t::NAMESPACE.into(),json!({"uninterpreted":"preserve"}));legacy.extensions=Some(ext);}Editor::new(legacy.clone(),"legacy:runtime".into()).unwrap()}else{editor()};
 if variant=="capacity"{let mut s=t::Store::default();for n in 100000..100512{s.definitions.insert(t::Id(n),t::Definition{id:t::Id(n),system:RecordId(1),name:format!("D{n}"),kind:t::Kind::Component});}let mut base=Snapshot::new(DocumentId("capacity:admission".into()));let mut ext=Extensions::default();ext.required_namespaces.push(t::NAMESPACE.into());ext.namespaces.insert(t::NAMESPACE.into(),serde_json::to_value(s).unwrap());base.extensions=Some(ext);base.next_id=100512;e=Editor::new(base,"capacity:runtime".into()).unwrap();}
 let before=e.snapshot.clone();let system=if variant=="wrong-system"{RecordId(1003)}else{RecordId(1)};assert!(a::prepare(&e,system,source(),payload()).is_err(),"{variant}");assert_eq!(e.snapshot,before);}
}
#[test]
fn admission_allocator_and_model_revision_exhaustion_refuse_without_partial_publication_or_history(){
 let mut e=editor();e.snapshot.next_id=u64::MAX;let before=e.snapshot.clone();assert!(a::prepare(&e,RecordId(1),source(),payload()).unwrap_err().contains("ID_EXHAUSTED"));assert_eq!(e.snapshot,before);let mut e=editor();e.snapshot.model_revision=u64::MAX;let p=plan(&e);let before=e.snapshot.clone();assert!(apply(&mut e,p).is_err());assert_eq!(e.snapshot,before);assert!(!e.can_undo());
}
#[test]
fn admission_bound_save_cold_and_captured_recovery_preserve_whole_prior_data_correspondence_and_all_eight_maps(){
 use mbse_model::{stage1_io::{Session,execute_write},native_views::{self as v,Views},native_views_io as io};let area=tempfile::tempdir_in(std::env::var_os("TMPDIR").unwrap()).unwrap();let mut session=Session::new(area.path()).unwrap();session.editor=Editor::new(editor().snapshot,session.editor.freshness().instance_id).unwrap();let before=session.editor.snapshot.clone();let mut doc:v::Document=serde_json::from_slice(VIEWS).unwrap();doc.profile=v::scenarios::RECOVERY_PROFILE.into();doc.binding=None;let views=Views::restore(&doc.encoded().unwrap(),&session.editor).unwrap();let p=plan(&session.editor);apply(&mut session.editor,p).unwrap();let expected=session.editor.snapshot.clone();preserved(&before,&expected);let dest=area.path().join("admitted.kernspan");let job=session.begin_save(&dest).unwrap();assert!(session.complete(execute_write(job)));let mut writes=io::Io::default();let side=dest.with_extension("mbse-views.json");let job=writes.begin(&session,&views,&side,io::Kind::Bound).unwrap();assert!(writes.complete(&session,&views,io::execute(job)));let cold=Session::open(area.path(),&dest).unwrap();assert_eq!(cold.editor.snapshot,expected);let decoded=Views::decode(&std::fs::read(&side).unwrap(),&cold.editor,&cold.native_checkpoint().unwrap().unwrap()).unwrap();let maps=["views","occurrences","edges","typed_ports","connector_edges","activity_diagrams","state_machine_diagrams","scenario_diagrams"];let old=serde_json::to_value(views.document()).unwrap();let new=serde_json::to_value(decoded.document()).unwrap();for map in maps{assert_eq!(old[map],new[map]);}assert!(!cold.editor.can_undo()&&!decoded.can_layout_history(false));let job=session.begin_recovery().unwrap();assert!(session.complete(execute_write(job)));let restored=Session::restore(area.path(),session.last_recovery().unwrap()).unwrap();let mut got=restored.editor.snapshot;got.document_id=expected.document_id.clone();assert_eq!(got,expected);let recovery=area.path().join("admitted-recovery.mbse-views.json");let destination=writes.freeze_destination(&session,&views,&recovery,io::Kind::Recovery).unwrap();let capture=views.capture(&session.editor);let job=writes.begin_captured(&session,&views,capture,destination).unwrap();assert!(writes.complete(&session,&views,io::execute(job)));let restored=Views::restore(&std::fs::read(recovery).unwrap(),&session.editor).unwrap();let new=serde_json::to_value(restored.document()).unwrap();for map in maps{assert_eq!(old[map],new[map]);}
}
